package main

import "fmt"

type Speaker interface {
	Speak() string
}

type Dog struct{}

// 不需要写 implements Speaker，有 Speak 方法就自动满足接口
func (d Dog) Speak() string {
	return "汪"
}

func main() {
	var s Speaker = Dog{}
	fmt.Println(s.Speak())

	var v any = 42
	if n, ok := v.(int); ok {
		fmt.Println("any 里装的是 int：", n)
	}
}

package main

import "fmt"

type MyError struct{}

func (e *MyError) Error() string {
	return "boom"
}

func bad() error {
	var p *MyError
	return p // 装进 error 的是「类型 *MyError + 值 nil」
}

func main() {
	err := bad()
	fmt.Println("err == nil ?", err == nil)
}

package main

import "fmt"

type Point struct {
	X int
	Y int
}

// 结构体按值传参，函数里改的是副本
func move(p Point) {
	p.X = 100
}

func main() {
	p := Point{X: 1, Y: 2}
	move(p)
	fmt.Println(p.X)
}

s := "你好"

// len 返回字节数，中文一个字占 3 个字节
fmt.Println(len(s))
// 转成 rune 切片才是字符数
fmt.Println(len([]rune(s)))
// range 迭代出的是码点，下标是字节偏移
for i, r := range s {
	fmt.Println(i, r)
}

